function calculateDockScale(cursorX, iconX, maxScale = 1.6, radius = 120) {
  const distance = Math.abs(cursorX - iconX);
  if (distance > radius) return 1;
  const factor = Math.cos((distance / radius) * (Math.PI / 2));
  return 1 + (maxScale - 1) * Math.pow(factor, 2);
}

class WindowManager {
  constructor() {
    this.activeZ = 100;
    this.windows = new Map();
  }
  focusWindow(winId) {
    this.activeZ++;
    const el = document.getElementById(winId);
    if (el) el.style.zIndex = this.activeZ;
  }
}

